class NotificationService {
  final FirebaseMessaging _messaging = FirebaseMessaging.instance;

  void initialize(BuildContext context) {
    // 1. 포그라운드 메시지 처리
    FirebaseMessaging.onMessage.listen((message) {
      debugPrint('포그라운드 메시지 수신!');
      debugPrint('제목: ${message.notification?.title}');
      debugPrint('내용: ${message.notification?.body}');

      // 커스텀 알림 표시 (flutter_local_notifications 사용)
      _showLocalNotification(message);

      // 또는 인앱 알림 표시
      _showInAppNotification(context, message);
    });

    // 2. 알림 탭으로 앱 열었을 때 (백그라운드 → 포그라운드)
    FirebaseMessaging.onMessageOpenedApp.listen((message) {
      debugPrint('알림 탭으로 앱 열림!');
      _handleNotificationTap(context, message);
    });

    // 3. 앱 종료 상태에서 알림 탭으로 열었을 때
    _checkInitialMessage(context);
  }

  Future<void> _checkInitialMessage(BuildContext context) async {
    final message = await _messaging.getInitialMessage();
    if (message != null) {
      debugPrint('앱 종료 상태에서 알림으로 열림!');
      _handleNotificationTap(context, message);
    }
  }

  void _showLocalNotification(RemoteMessage message) {
