import 'package:firebase_messaging/firebase_messaging.dart';

class TopicService {
  final FirebaseMessaging _messaging = FirebaseMessaging.instance;

  // 토픽 구독
  Future<void> subscribeToTopic(String topic) async {
    await _messaging.subscribeToTopic(topic);
    debugPrint('$topic 토픽 구독됨');
  }

  // 토픽 구독 해제
  Future<void> unsubscribeFromTopic(String topic) async {
    await _messaging.unsubscribeFromTopic(topic);
    debugPrint('$topic 토픽 구독 해제됨');
  }
}

// 사용 예시
class NotificationSettingsScreen extends StatefulWidget {
  const NotificationSettingsScreen({super.key});

  @override
  State<NotificationSettingsScreen> createState() => _NotificationSettingsScreenState();
}

class _NotificationSettingsScreenState extends State<NotificationSettingsScreen> {
  final _topicService = TopicService();

  bool _promotionEnabled = true;
  bool _newsEnabled = true;
  bool _updateEnabled = true;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('알림 설정')),
      body: ListView(
        children: [
          SwitchListTile(
            title: const Text('프로모션 알림'),
            subtitle: const Text('할인, 이벤트 정보'),
            value: _promotionEnabled,
            onChanged: (value) async {
              setState(() => _promotionEnabled = value);
              if (value) {
                await _topicService.subscribeToTopic('promotions');
              } else {
                await _topicService.unsubscribeFromTopic('promotions');
              }
            },
          ),
          SwitchListTile(
            title: const Text('뉴스 알림'),
            subtitle: const Text('새로운 소식, 공지사항'),
            value: _newsEnabled,
            onChanged: (value) async {
              setState(() => _newsEnabled = value);
              if (value) {
                await _topicService.subscribeToTopic('news');
              } else {
                await _topicService.unsubscribeFromTopic('news');
              }
            },
          ),
          SwitchListTile(
            title: const Text('업데이트 알림'),
            subtitle: const Text('앱 업데이트, 새 기능'),
            value: _updateEnabled,
            onChanged: (value) async {
              setState(() => _updateEnabled = value);
              if (value) {
                await _topicService.subscribeToTopic('updates');
              } else {
                await _topicService.unsubscribeFromTopic('updates');
              }
            },
          ),
        ],
      ),
    );
  }
}

